// Generated by scripts/gen-types.mjs from fec-parser (via ts-rs). Do not edit.
// Tables tabulated from fec-parser's label functions by src/bin/gen-types.rs.

const lookup = (table: Readonly<Record<string, string>>, key: string): string | null =>
  Object.hasOwn(table, key) ? table[key]! : null;

const ELECTIONCODELABEL_TABLE: Readonly<Record<string, string>> = {
  "C": "Convention",
  "E": "Recount",
  "G": "General",
  "O": "Other",
  "P": "Primary",
  "R": "Runoff",
  "S": "Special"
};

/**
 * The election type for a cover record's election code (`P2026` →
 * `"Primary"`), from the code's first letter.
 *
 * Letters per the FEC e-filing format specification, "Election Code (A.K.A.
 * Primary/General Indicator or PGI)": `P` Primary, `G` General, `O` Other,
 * `C` Convention, `R` Runoff, `S` Special, `E` Recount, each followed by the
 * election year (FEC_Format_v8.4.pdf p11). Unknown letters return `None`.
 *
 * Returns `null` for `null`, `undefined` and unknown codes. Mirrors Rust's
 * `fec_parser::covers::election_code_label`.
 *
 * @category Labels
 */
export function electionCodeLabel(code: string | null | undefined): string | null {
  if (code == null) return null;
  return lookup(ELECTIONCODELABEL_TABLE, code.trim().charAt(0).toUpperCase());
}

